const abs = (x: number, y: number, s: CSSProperties = {}): CSSProperties => ({ position: 'absolute', left: x, top: y, ...s })
const hex = (c: number[]) => `rgb(${c[0]} ${c[1]} ${c[2]})`

function Field() {
  // one horizontal gradient per mesh row, stacked as 16px bands with a vertical blend to the next row
  const { xs, grid } = MESH
  return (
    <svg width={W} height={H} style={{ position: 'absolute', inset: 0 }} aria-hidden>
      <defs>
        {grid.map(([y, row], i) => (
          <linearGradient key={i} id={`m${i}`} x1="0" x2={W} y1="0" y2="0" gradientUnits="userSpaceOnUse">
            {row.map((c, k) => <stop key={k} offset={xs[k] / W} stopColor={hex(c)} />)}
          </linearGradient>
        ))}
        {grid.slice(0, -1).map((_, i) => (
          <linearGradient key={i} id={`v${i}`} x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="#fff" stopOpacity="0" /><stop offset="1" stopColor="#fff" stopOpacity="1" /></linearGradient>
        ))}
        {grid.slice(0, -1).map((_, i) => <mask key={i} id={`k${i}`}><rect x={0} y={grid[i][0]} width={W} height={grid[i + 1][0] - grid[i][0] + 0.5} fill={`url(#v${i})`} /></mask>)}
      </defs>
      {grid.slice(0, -1).map(([y], i) => (
        <g key={i}>
          <rect x={0} y={y} width={W} height={grid[i + 1][0] - y + 0.5} fill={`url(#m${i})`} />
          <rect x={0} y={y} width={W} height={grid[i + 1][0] - y + 0.5} fill={`url(#m${i + 1})`} mask={`url(#k${i})`} />
        </g>
      ))}
      <rect x={0} y={H - 1} width={W} height={1} fill={`url(#m${grid.length - 1})`} />
      {LINES.map(([a, d], i) => <path key={i} d={d} fill={`rgba(0,0,0,${a})`} />)}
    </svg>
  )
}

const ink: CSSProperties = { background: 'linear-gradient(#333333, #1d1d1d)', boxShadow: '0 1px 2px rgb(8 8 8 / .2), 0 3px 4px rgb(8 8 8 / .06), inset 0 1px 0 rgb(255 255 255 / .12)', color: '#fff' }

